-- Restore the static Lion's Landing scenario environment (map 1103).
-- Spawn data adapted from the GPL-2.0 Legends of Azeroth Pandaria 5.4.8 world release 2024-07-22.
-- Source: https://github.com/Legends-of-Azeroth/Legends-of-Azeroth-Pandaria-5.4.8/releases

CREATE TABLE IF NOT EXISTS `_backup_20260919_lions_landing_creature` LIKE `creature`;
CREATE TABLE IF NOT EXISTS `_backup_20260919_lions_landing_gameobject` LIKE `gameobject`;

DELETE FROM `creature` WHERE `map` = 1103;

DELETE FROM `gameobject` WHERE `map` = 1103;

ON DUPLICATE KEY UPDATE `name`=VALUES(`name`),`position_x`=VALUES(`position_x`),`position_y`=VALUES(`position_y`),`position_z`=VALUES(`position_z`),`orientation`=VALUES(`orientation`);
